import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/tes0')
from h import *
X=[]
X.append(r(9228604,"¡Ñoquis veganos de calabaza hechos desde cero!","¡Ñoquis veganos de calabaza hechos desde cero, suaves como una almohada y que hacen agua la boca!","8 porciones","1 porción",
["3 libras de calabaza para pay o 2 tazas de puré de calabaza","sal + pimienta para espolvorear sobre la calabaza","3-3 ¼ tazas de harina integral para repostería","1 cucharadita de sal marina","½ cucharadita de salvia molida","⅛ de cucharadita de nuez moscada molida",("Salsa vegana de “mantequilla” con salvia","1 taza de anacardos (nueces de la India) crudos"),("Salsa vegana de “mantequilla” con salvia","¾ de taza de agua caliente"),("Salsa vegana de “mantequilla” con salvia","2 dientes de ajo"),("Salsa vegana de “mantequilla” con salvia","½ cucharadita de salvia molida"),("Salsa vegana de “mantequilla” con salvia","sal + pimienta al gusto"),("O use otra salsa","salsa de tomate o salsa marinara de su elección"),("O use otra salsa","salsa Alfredo"),("O use otra salsa","salsa boloñesa de coliflor"),("Para decorar","queso parmesano vegano"),("Para decorar","hojas de salvia fresca (ideal con la salsa de mantequilla)"),("Para decorar","hojas de albahaca fresca (ideal con la salsa de tomate)"),("Para decorar","perejil fresco (ideal con la salsa Alfredo)")],
[("Para el puré de calabaza","Precaliente el horno a 400 grados en modo de asado con convección y cubra una bandeja para hornear con papel pergamino."),("Para el puré de calabaza","Corte la calabaza por la mitad o en tercios y retire las semillas con una cuchara. Coloque la calabaza con la cáscara hacia abajo en la bandeja. Espolvoree con sal y pimienta y ase hasta que un tenedor atraviese fácilmente la pulpa de la calabaza, aprox. 40 minutos, y luego retire del horno."),("Para el puré de calabaza","Saque la pulpa de la calabaza con una cuchara, sepárela de la cáscara y pásela a un procesador de alimentos o licuadora y procese hasta que quede muy suave. Trabaje por tandas, según sea necesario. Mida 2 tazas de puré y resérvelo para preparar los ñoquis."),("Para los ñoquis veganos de calabaza","En un tazón grande, ponga 2 tazas de puré de calabaza, 3 tazas de harina y los condimentos. Mezcle para integrar y pase a una superficie de trabajo grande enharinada."),("Para los ñoquis veganos de calabaza","Amase la masa con las manos, agregando un poco de harina a la superficie y a las manos según sea necesario para evitar que se pegue. Use la menor cantidad de harina posible para evitar que se pegue, sin agregar demasiada. La masa debe quedar un poco pegajosa; esto es normal. Tenga cuidado de no agregar demasiada harina, o los ñoquis no quedarán suaves."),("Para los ñoquis veganos de calabaza","Use un rodillo para estirar la masa hasta que tenga aprox. media pulgada de grosor."),("Para los ñoquis veganos de calabaza","Luego espolvoree un cuchillo afilado o un cortador de pizza con harina y corte la masa en tiras de 1 pulgada. Después, corte cada tira en trozos de aprox. media pulgada para formar un patrón de cuadrícula. Espolvoree los trozos con un poco más de harina si es necesario."),("Para los ñoquis veganos de calabaza","Opcional: Use una tabla para ñoquis enharinada o un tenedor grande para presionar y rodar suavemente cada ñoqui y formar líneas. Vuelva a enharinar la tabla o el tenedor para evitar que se pegue."),("Para los ñoquis veganos de calabaza","Coloque los ñoquis preparados en una sola capa en una bandeja cubierta con papel pergamino. Si va a cocinar los ñoquis en un plazo de 2 horas, puede dejarlos a temperatura ambiente. De lo contrario, siga las instrucciones de almacenamiento en las notas a continuación."),("Para cocinar los ñoquis","Esto rinde una tanda grande, así que puede congelar algunos y cocinar otros de inmediato."),("Para cocinar los ñoquis","Para cocinar, hierva una olla grande con agua con abundante sal. Luego deje caer los ñoquis en el agua hirviendo, trabajando por tandas para evitar que se amontonen. Hierva hasta que estén tiernos y floten en la superficie del agua, aprox. 5-10 minutos. NOTA: El tiempo de cocción variará según qué tan llena esté la olla, la harina que use y si usa puré de calabaza casero o de lata."),("Para cocinar los ñoquis","Retire los ñoquis con una espumadera y colóquelos en un tazón para servir. Repita con los ñoquis restantes hasta que haya cocinado la cantidad deseada. Sirva con su salsa y guarniciones favoritas."),("Para la salsa vegana de mantequilla con salvia","Ponga todos los ingredientes en una licuadora de alta potencia y procese hasta que quede suave. Sirva sobre los ñoquis y decore con salvia fresca.")],
["No trabaje demasiado la masa. No desea amasar en exceso la masa o los ñoquis quedarán más firmes, y saben mejor cuando están suaves. Trabájela durante aproximadamente 1-2 minutos y no más. No se exceda con la harina. Use la suficiente para que la masa no se pegue a las manos ni a la superficie de trabajo, pero no agregue demasiada o los ñoquis quedarán duros. Un poco de pegajosidad está bien. Una calabaza para pay de 3 libras producirá aprox. 2 tazas de puré de calabaza, que es lo que se necesita para esta receta. Si le sobra, refrigérelo o congélelo para usarlo en otra receta. Use solo 2 tazas para esta receta, o aumente la harina para compensar la diferencia si desea usar más. Tenga harina extra a la mano mientras trabaja. La necesitará para espolvorear la superficie de trabajo, las manos, el rodillo, el cuchillo, la tabla para ñoquis, etc. Asegúrese de mantener los ñoquis en una sola capa una vez preparados para evitar que se peguen entre sí. Para ahorrar tiempo, puede usar 2 tazas de puré de calabaza de lata y omitir el asado de la calabaza, con resultados similares. Si no tiene una tabla para ñoquis o no desea hacer las líneas, puede omitir este paso por completo. Las líneas son decorativas y no afectarán el resultado ni el sabor del platillo. Una vez preparados los ñoquis (pero sin cocinar), puede dejarlos a temperatura ambiente hasta por 2 horas en una sola capa. O refrigere de 1 a 2 días si trabaja con anticipación. Congele los ñoquis sin cocinar en una sola capa durante unas horas, hasta que estén sólidos. Luego, pase a un recipiente cerrado o una bolsa con cierre y manténgalos congelados hasta por 3 meses. Cocínelos congelados, NO LOS DESCONGELE. Los ñoquis de calabaza tardan un poco más en cocinarse que las versiones de papa. No necesariamente están listos en cuanto flotan en la superficie. Revise qué tan tiernos están alrededor de los 5 minutos y continúe cocinando hasta que estén suaves. ***La información nutricional representa ⅛ de los ñoquis de calabaza con ⅛ de la salsa vegana rápida de mantequilla con salvia. Si usa otra salsa, la información nutricional variará. Los ñoquis cocidos sobrantes se conservan en el refrigerador de 2 a 3 días."],[]))
X.append(r(9228909,"Costillas de elote en freidora de aire","¡Costillas de elote pegajosas, dulces y ahumadas en freidora de aire! Este fantástico acompañamiento es increíblemente delicioso, muy sencillo de preparar y requiere solo DOS ingredientes.","4 porciones","1 porción",
["2 elotes","3-4 cucharadas de salsa barbacoa"],
["Retire las hojas del elote y use un cuchillo afilado para cortar cada elote por la mitad para que sea más fácil cortarlo en cuartos. Luego coloque cada pieza de pie (con el lado plano que acaba de cortar sobre la tabla para cortar, para mayor estabilidad) y córtela por la mitad en vertical. Después coloque esas piezas con el centro hacia abajo y córtelas por la mitad de nuevo. Obtendrá 8 costillas de elote de cada elote, para un total de 16 piezas. El objetivo es no aplastar los granos, por lo que este método de corte funciona mejor. Vea las fotos del proceso arriba para mayor claridad.","Unte cada costilla de elote con salsa BBQ y colóquelas en la canasta de la freidora en una capa uniforme. No hay problema si se superponen un poco. Cocine en la freidora de aire a 380°F/193°C durante 10-12 minutos y disfrute."],
["Elija elotes frescos, con granos más gruesos. Las hojas deben estar bien ajustadas, de color verde brillante, y no volverse amarillas ni secas. Tenga mucha precaución al cortar el elote en “costillas”."],[]))
X.append(r(9228970,"Muffins veganos de fresa","Muffins veganos de fresa húmedos, ligeramente dulces, nutritivos y sin gluten.","12 muffins","1 porción",
["1 taza de leche de soya (o leche de almendra)","1 cucharadita de vinagre de manzana (o jugo de limón)","1/3 de taza de compota de manzana sin azúcar","2 cucharaditas de extracto puro de vainilla","270 gramos de harina de avena (aprox. 3 tazas, colocada con cuchara + nivelada)","1/3 de taza de azúcar de coco sin refinar","2 cucharaditas de polvo para hornear","1 taza de fresas picadas en cubos"],
["Precaliente el horno a 350℉/176℃ y engrase o cubra un molde para muffins con capacillos de papel pergamino, suficientes para hacer 12 muffins.","Combine la leche de soya y el vinagre de manzana en un tazón grande y déjelos reposar durante 5 minutos para que se cuajen, espesen y formen su suero de leche vegano.","Una vez cuajada, agregue la compota de manzana y la vainilla al mismo tazón y revuelva para integrar. Luego agregue todos los ingredientes secos: la harina, el azúcar y el polvo para hornear, y revuelva hasta que se integren. Por último, incorpore con movimientos envolventes las fresas picadas.","Divida la masa de los muffins entre los 12 moldes y hornee en el horno precalentado de 18 a 22 minutos, o hasta que un palillo insertado en el centro salga limpio.","Deje reposar los muffins durante 10 minutos antes de pasarlos a una rejilla para que sigan enfriándose."],[],[]))
X.append(r(9229405,"Calabacitas con limón en freidora de aire","¡Estas sabrosas calabacitas con limón son fáciles de preparar y usan solo 5 ingredientes! Súper sencillas, deliciosas y el acompañamiento perfecto que está listo en un santiamén.","3 porciones","1 porción",
["3 calabacitas medianas en rodajas de ⅛ de pulgada (aprox. 6 tazas)","2 cucharadas de jugo de limón, aprox. un limón mediano","½ cucharadita de ajo en polvo","½ cucharadita de orégano seco","¼ de cucharadita de sal marina o al gusto"],
["Corte las calabacitas en rodajas de aprox. 1/8 de pulgada de grosor y colóquelas en un tazón.","Luego combine todos los demás ingredientes en un tazón pequeño y vierta la mezcla sobre las rodajas de calabacita. Mezcle bien para asegurarse de que cada pieza quede cubierta, usando las manos para separar las rodajas a medida que avanza.","Coloque las calabacitas en la canasta y cocine en la freidora de aire a 400 grados F durante 20-25 minutos, hasta que estén doradas. Sacuda suavemente la canasta o mezcle las calabacitas cada 5 minutos aproximadamente para una cocción uniforme."],
["Haga lo posible por cortar las calabacitas lo más uniformes posible para que se cocinen de manera pareja. Sacuda la canasta, o mezcle suavemente, cada 5 minutos aproximadamente durante la cocción. Esto asegurará una cocción uniforme y evitará que las calabacitas se peguen a la canasta. Pruebe diferentes mezclas de especias para variar cada vez. ¡Vea mis sugerencias arriba! Las sobras se conservan en el refrigerador en un recipiente cerrado de 3 a 4 días."],[]))
X.append(r(9229801,"Zanahorias baby con arce y ajo en freidora de aire","¡Un delicioso giro de la receta de miel y ajo les ofrece estas zanahorias baby con arce y ajo, súper sabrosas!","4 porciones","1 porción",
["1 paquete de 12 onzas de zanahorias baby","2 dientes de ajo picados finamente","1 cucharada de jarabe de arce","1 cucharada de tamari o salsa de soya","1 cucharada de aceite de aguacate o mantequilla o margarina derretida (opcional)*","perejil o cilantro fresco (opcional, para decorar)"],
["Ponga las zanahorias y los demás ingredientes (excepto el perejil) en un tazón pequeño. Mezcle hasta que queden cubiertas de manera uniforme.","Luego use una espumadera para colocar las zanahorias en la canasta de la freidora de aire. (No vierta todo). Acomode en una sola capa y cocine en la freidora de aire a 400 grados F durante 12-16 minutos. Sacuda o mezcle las zanahorias cada 5 minutos aproximadamente.","Cuando estén cocidas a su gusto, retire las zanahorias de la canasta y mézclelas con el glaseado restante si lo desea. Luego sirva con hierbas frescas y disfrute."],
["* Para una versión sin aceite, omita el aceite o la mantequilla y use una cucharada de caldo en su lugar. El tamaño de las zanahorias y el modelo de la freidora determinarán el tiempo de cocción. Asegúrese de revisar las zanahorias con frecuencia hacia el final de la cocción. Las sobras se conservan en el refrigerador de 3 a 4 días, pero saben mejor recién hechas."],[]))
X.append(r(9231462,"Panqueques veganos saludables de limón y semillas de amapola","Estos panqueques veganos saludables de limón y semillas de amapola son ligeramente ácidos, con una textura encantadora gracias a las semillas de amapola.","12 panqueques de 4\"","1 panqueque",
[("Ingredientes húmedos","1.5 tazas de leche de soya"),("Ingredientes húmedos","4 cucharadas de jugo de limón, de aprox. 1 limón"),("Ingredientes húmedos","1 cucharada de ralladura de limón, de aprox. 1 limón"),("Ingredientes húmedos","2 cucharaditas de extracto puro de vainilla"),("Ingredientes secos","180 gramos de harina de avena, aprox. 2 tazas"),("Ingredientes secos","3 cucharadas de semillas de amapola"),("Ingredientes secos","2 cucharaditas de polvo para hornear"),("Ingredientes secos","2 cucharadas de semillas de linaza molidas"),("Aderezos opcionales","jarabe de arce"),("Aderezos opcionales","frutos rojos frescos")],
["Ponga la leche de soya, el jugo de limón y la ralladura de limón en un tazón pequeño y deje reposar durante 5 minutos para que espese y se cuaje.","En un tazón grande, ponga todos los ingredientes secos y bata para integrar. Luego agregue la leche cuajada/espesada y la vainilla y mezcle hasta que se integren. Deje reposar la masa de los panqueques durante 5 minutos mientras precalienta la plancha antiadherente.","Vierta la masa con un cucharón sobre la plancha para hacer panqueques de aprox. 4 pulgadas de diámetro, extendiéndola suavemente a medida que la vierte.","Cocine los panqueques de 4 a 5 minutos, luego voltéelos y cocine otros 3-4 minutos más hasta que los bordes estén dorados. Sirva con los aderezos de su elección y disfrute."],
["Use polvo para hornear fresco y activo. El polvo para hornear que se ha abierto y lleva varios meses en la despensa puede empezar a perder su efectividad. No es necesario mezclar en exceso la masa de los panqueques. Si quedan algunos grumos, está perfectamente bien. Simplemente mezcle hasta que se integre y no queden restos de harina. Precaliente la sartén o plancha. Debe estar caliente antes de verter la masa de los panqueques para evitar que se peguen y para una cocción uniforme. Use fuego medio para cocinar los panqueques. Aunque la sartén debe estar caliente, eso no significa que deba usar fuego alto. Esto puede provocar una cocción despareja, con el exterior crujiente y el centro blando. Voltee los panqueques UNA SOLA VEZ. Cuando los bordes estén dorados y hayan cocinado durante al menos 3-4 minutos, voltéelos. Voltearlos demasiadas veces puede hacer que se desinflen y den como resultado una textura más densa. La masa espesará mientras reposa, así que si se vuelve demasiado espesa entre tandas de panqueques, agregue 1-2 cucharadas de leche vegetal al tazón. Las sobras se conservan en el refrigerador de 2 a 3 días o congeladas hasta por 3 meses."],[]))
X.append(r(9235323,"Burritos veganos de yaca BBQ","¡Los burritos veganos suben de nivel con yaca BBQ ahumada, ácida e increíblemente sabrosa!","6 porciones","1 porción",
["1 lata de 20 onzas de yaca verde joven en salmuera o agua, NO en almíbar",("Para la salsa","¼ de taza de cátsup"),("Para la salsa","¼ de taza de vinagre de manzana"),("Para la salsa","2 cucharadas de agua"),("Para la salsa","1 cucharada de salsa de soya o tamari si evita el gluten"),("Para la salsa","1 cucharada de jarabe de arce"),("Para la salsa","1 cucharada de mostaza amarilla"),("Para la salsa","1 cucharadita de pimentón ahumado o humo líquido"),("Para la salsa","1 cucharadita de ajo en polvo"),("Para la salsa","1 cucharadita de cebolla en polvo"),("Para los burritos veganos","tortillas de harina de su elección, sin gluten si lo prefiere"),("Para los burritos veganos","arroz cocido"),("Para los burritos veganos","frijoles negros"),("Para los burritos veganos","maíz"),("Para los burritos veganos","tomates picados en cubos"),("Para los burritos veganos","aceitunas negras"),("Para los burritos veganos","jalapeño en rebanadas"),("Para los burritos veganos","cilantro fresco"),("Para los burritos veganos","salsa"),("Para los burritos veganos","guacamole"),("Para los burritos veganos","crema de anacardos (nueces de la India)")],
["Escurra y enjuague muy bien la yaca para eliminar el sabor de la salmuera. Luego use las manos (o dos tenedores sobre una tabla para cortar) para separar los trozos de yaca hasta que quede desmenuzada. Colóquela en un tazón pequeño y reserve.","En otro tazón pequeño, ponga TODOS los ingredientes de la salsa y bata para integrar. Luego viértala sobre la yaca y mezcle para cubrirla de manera uniforme. Elija un método de cocción a continuación.",("Instrucciones para el horno","Precaliente el horno a 425 grados F y cubra una bandeja para hornear con papel pergamino. Acomode la yaca cubierta en la bandeja y hornee durante 20 minutos, mezclando una vez a la mitad del tiempo. Retire del horno."),("Instrucciones para Instant Pot","Ponga la yaca cubierta en la Instant Pot y cocine a alta presión durante 5 minutos. Luego libere la presión de forma natural durante 10 minutos. Si no se ha liberado por completo después de 10 minutos, libere rápidamente la presión restante y abra la tapa cuando sea seguro hacerlo."),("Instrucciones para estufa","Coloque la yaca cubierta en una sartén mediana y cocine a fuego medio-alto, revolviendo de vez en cuando, hasta que se haya absorbido casi toda la salsa. Esto tardará unos 10-12 minutos."),("Arme sus burritos veganos","Arme el burrito de yaca con los aderezos deseados y la tortilla de su elección, o prepare un bowl de burrito de yaca sobre una cama de lechuga con los aderezos deseados encima.")],
["No rellene demasiado los burritos veganos o serán difíciles de cerrar y sostener y podrían desbaratarse. ¡Menos es más! Guarde los aderezos sobrantes en recipientes separados en el refrigerador de 3 a 4 días y arme el burrito de yaca justo antes de comer para evitar que la tortilla se humedezca."],[]))
X.append(r(9237195,"Camotes veganos rellenos con frijoles horneados","¡Estos camotes veganos rellenos están llenos de frijoles horneados y cubiertos con guacamole! ¡Hola, comida reconfortante!","4 porciones","1 porción",
["4 camotes bien lavados",("Para los frijoles horneados","1 taza (200 g) de frijoles blancos pequeños (navy)/blancos secos, remojados toda la noche"),("Para los frijoles horneados","1.5 tazas de caldo de verduras bajo en sodio"),("Para los frijoles horneados","¼ de taza de jarabe de arce"),("Para los frijoles horneados","1 cucharadita de mostaza amarilla"),("Para los frijoles horneados","½ cucharadita de ajo en polvo"),("Para los frijoles horneados","½ cucharadita de cebolla en polvo"),("Para los frijoles horneados","1 cucharada de pimentón ahumado"),("Para los frijoles horneados","½ cucharadita de sal marina"),("Aderezos opcionales","guacamole"),("Aderezos opcionales","crema de anacardos (nueces de la India)"),("Aderezos opcionales","salsa"),("Aderezos opcionales","perejil, cilantro o cebolla de verdeo frescos")],
["Precaliente el horno a 425°F/218°C y cubra una bandeja para hornear con papel pergamino. Pique los camotes con un tenedor o un cuchillo de 5 a 6 veces alrededor del camote. (Esto evitará que exploten en el horno). Luego hornee de 45 a 60 minutos, o hasta que se atraviesen fácilmente con un tenedor.","Mientras tanto, ponga todos los ingredientes de los frijoles horneados en la Instant Pot, revuelva y cierre la tapa. Asegúrese de que la válvula esté en la posición de sellado y programe a alta presión durante 40 minutos. (Tardará unos 10 minutos en acumular presión antes de iniciar la cuenta regresiva). Cuando termine el temporizador, puede liberar rápidamente la válvula de vapor.","Mientras se cocinan los frijoles y las papas, prepare el guacamole o cualquier otro aderezo que vaya a usar.","Cuando los camotes estén cocidos, retírelos del horno y ábralos a lo largo, sin cortar por completo. Luego machaque suavemente el interior para crear un hueco y sirva con una porción generosa de frijoles horneados y decore como desee."],
["Si olvidó remojar los frijoles, use este método de remojo rápido. Ponga los frijoles en una olla mediana con suficiente agua para cubrirlos aprox. 2 pulgadas por encima de los frijoles. Coloque la tapa en la olla y hierva en la estufa. Cuando hierva, apague el fuego y déjelos reposar de 45 a 60 minutos. Luego escurra y cocine según las indicaciones.","Los frijoles horneados pueden verse aguados al retirar por primera vez la tapa de la Instant Pot. Solo revuelva, deje la tapa fuera y deje reposar los frijoles unos minutos mientras corta las papas. Absorberán rápidamente la salsa y el sabor.","Si los camotes son grandes, pueden necesitar cerca de 55-60 minutos de horneado. Cuando estén lo bastante suaves para pincharlos con un tenedor, estarán listos.","Si no tiene una Instant Pot, pruebe este método de olla de cocción lenta O visite la publicación de arriba en “equipo” para un método en estufa.","Guarde las sobras por separado en el refrigerador de 3 a 4 días y arme los camotes rellenos justo antes de disfrutarlos."],[]))
X.append(r(9237341,"Latte vegano de especias de calabaza [sin azúcar]","Este fácil latte vegano de especias de calabaza es delicioso, fácil de preparar y está listo en 5 minutos. Sin jarabes endulzados artificialmente, solo ingredientes reales y nutritivos.","2 porciones","1 porción",
["3 tazas de leche de su elección (me gusta la de soya, pero la de almendra o anacardos también funciona bien)","3 cucharadas de puré de calabaza","1 cucharada de extracto puro de vainilla","½ cucharadita de canela","¼ de cucharadita de nuez moscada","⅛ de cucharadita de jengibre molido","¾ de taza de café fuerte caliente (yo uso espresso fuerte)"],
["En una olla pequeña, combine todos los ingredientes, excepto el café, y caliente a fuego medio, vigilando con cuidado que no hierva. Revuelva con frecuencia y caliente hasta alcanzar la temperatura deseada.","Mientras tanto, divida el café caliente o espresso entre dos tazas. Luego vierta encima la leche caliente con especias de calabaza. ¡Revuelva y disfrute!"],
["Para ahorrar tiempo, y si no tiene las especias individuales indicadas, puede sustituirlas por ¾ de cucharadita de especias para pay de calabaza. Use café espresso para obtener el mejor sabor. Espolvoree el latte con una pizca de canela o una pizca de mezcla de especias para pay de calabaza para dar más sabor, si lo desea. Si lo desea dulce, agregue 1-2 cucharaditas de azúcar de coco sin refinar, o el endulzante de su elección, a cada taza. Para una versión sin soya, sustituya la leche de soya por leche de anacardos (nueces de la India) sin azúcar, leche de almendra, leche de avena o la de su elección."],[]))
save(11,X)
